CREATE OR REPLACE FUNCTION public.platform_apply_case_attributes(target_workspace_id uuid, actor_user_id uuid, target_case_id uuid, expected_updated_at timestamp with time zone, identity_changes jsonb, expected_owner_updated_at timestamp with time zone, change_data_owner boolean DEFAULT false, new_data_owner_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE result jsonb; responsibilities jsonb; owner_version timestamptz;
BEGIN
 -- Same workspace -> Case lock order as admission and responsibility assignment.
 PERFORM 1 FROM workspaces WHERE id=target_workspace_id FOR UPDATE;
 result=public.platform_update_case_identity(target_workspace_id,actor_user_id,target_case_id,expected_updated_at,identity_changes);
 SELECT updated_at INTO owner_version FROM dation_private.workflow_stage_assignments
  WHERE workspace_id=target_workspace_id AND decision_case_id=target_case_id AND stage_key='data_owner';
 IF owner_version IS DISTINCT FROM expected_owner_updated_at THEN RAISE EXCEPTION 'Assignment changed' USING ERRCODE='55006'; END IF;
 IF change_data_owner THEN
  responsibilities=public.platform_workflow_responsibilities(target_workspace_id,actor_user_id,target_case_id,'write','data_owner',expected_owner_updated_at,new_data_owner_user_id,NULL);
 ELSE
  responsibilities=public.platform_workflow_responsibilities(target_workspace_id,actor_user_id,target_case_id);
 END IF;
 -- Any ownership/CAS/permission failure rolls back the identity update as well.
 RETURN result||jsonb_build_object('workflow_responsibilities',responsibilities);
END; $function$

CREATE OR REPLACE FUNCTION public.platform_assign_decision(target_workspace_id uuid, actor_user_id uuid, target_case_id uuid, target_node_id text, expected_updated_at timestamp with time zone, new_owner_user_id uuid, new_approver_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE assignment decision_assignments;
BEGIN
 PERFORM 1 FROM workspaces WHERE id=target_workspace_id FOR UPDATE;
 PERFORM dation_private.team_actor(target_workspace_id,actor_user_id,true);
 PERFORM 1 FROM decision_cases WHERE workspace_id=target_workspace_id AND id=target_case_id AND status<>'archived' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Case not found or archived' USING ERRCODE='P0002'; END IF;
 IF target_node_id NOT IN('logistics_assignment','logistics_scheduling') OR target_node_id IS NULL THEN RAISE EXCEPTION 'Invalid node' USING ERRCODE='22023'; END IF;
 SELECT * INTO assignment FROM decision_assignments WHERE workspace_id=target_workspace_id AND decision_case_id=target_case_id AND node_id=target_node_id FOR UPDATE;
 IF assignment.updated_at IS DISTINCT FROM expected_updated_at THEN RAISE EXCEPTION 'Assignment changed' USING ERRCODE='55006'; END IF;
 IF new_approver_user_id IS NOT NULL AND new_approver_user_id IS DISTINCT FROM new_owner_user_id AND new_approver_user_id IS DISTINCT FROM assignment.approver_user_id THEN
  RAISE EXCEPTION 'Use the Decision Owner; separate approvers are retired' USING ERRCODE='22023'; END IF;
 IF new_owner_user_id IS DISTINCT FROM assignment.owner_user_id THEN
  IF new_owner_user_id IS NOT NULL AND NOT dation_private.responsibility_eligible(target_workspace_id,new_owner_user_id,'decision_owner') THEN
   RAISE EXCEPTION 'Assignee responsibility is not eligible' USING ERRCODE='22023'; END IF;
  INSERT INTO decision_assignments(workspace_id,decision_case_id,node_id,owner_user_id)
   VALUES(target_workspace_id,target_case_id,target_node_id,new_owner_user_id)
   ON CONFLICT(decision_case_id,node_id) DO UPDATE SET owner_user_id=excluded.owner_user_id,updated_at=clock_timestamp()
   RETURNING * INTO assignment;
  INSERT INTO audit_events(workspace_id,actor_user_id,event_type,object_type,object_id,decision_case_id,node_id,metadata_json)
   VALUES(target_workspace_id,actor_user_id,'decision.owner_changed','decision_case',target_case_id,target_case_id,target_node_id,
    jsonb_build_object('stage_key',target_node_id,'new_user_id',new_owner_user_id));
 END IF;
 RETURN jsonb_build_object('updated_at',assignment.updated_at);
END; $function$

CREATE OR REPLACE FUNCTION public.platform_create_workspace(actor_user_id uuid, workspace_name text, workspace_country text, workspace_timezone text, workspace_currency text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE target uuid;
BEGIN
 IF NOT (SELECT admissions_open FROM dation_private.platform_release WHERE singleton) OR NOT EXISTS(
  SELECT 1 FROM auth.users WHERE id=actor_user_id AND email_confirmed_at IS NOT NULL) THEN RAISE EXCEPTION 'Identity denied' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(actor_user_id::text,0));
 IF EXISTS(SELECT 1 FROM workspace_members WHERE user_id=actor_user_id) OR EXISTS(
  SELECT 1 FROM dation_private.legacy_owners o JOIN auth.users u ON lower(u.email)=o.email WHERE u.id=actor_user_id) THEN
  RAISE EXCEPTION 'Existing membership must be resolved first' USING ERRCODE='22023'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=workspace_timezone) THEN RAISE EXCEPTION 'Invalid timezone' USING ERRCODE='22023'; END IF;
 INSERT INTO profiles(id) VALUES(actor_user_id) ON CONFLICT DO NOTHING;
 INSERT INTO workspaces(name,country,timezone,currency,created_by) VALUES(trim(workspace_name),workspace_country,workspace_timezone,workspace_currency,actor_user_id) RETURNING id INTO target;
 INSERT INTO workspace_members(workspace_id,user_id,access_role,joined_at) VALUES(target,actor_user_id,'admin',now());
 INSERT INTO workspace_ddas(workspace_id,dda_id,status)
  SELECT target,id,CASE WHEN id='logistics' THEN 'enabled' ELSE 'coming_soon' END
  FROM unnest(ARRAY['logistics','production','inventory','demand','purchasing','maintenance','pricing']) id;
 INSERT INTO audit_events(workspace_id,actor_user_id,event_type) VALUES(target,actor_user_id,'workspace.created');
 UPDATE profiles SET active_workspace_id=target,updated_at=now() WHERE id=actor_user_id;
 RETURN jsonb_build_object('workspace_id',target);
END; $function$

CREATE OR REPLACE FUNCTION public.platform_dataset_delete(target_workspace_id uuid, actor_user_id uuid, target_dataset_id uuid, operation text DEFAULT 'prepare'::text, operation_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE target datasets; intent dation_private.dataset_deletions;
BEGIN
 PERFORM dation_private.data_actor(target_workspace_id,actor_user_id,true);
 IF operation NOT IN('prepare','finish') THEN RAISE EXCEPTION 'Invalid delete operation' USING ERRCODE='22023'; END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('dation-data:'||target_workspace_id::text,0)) THEN
  RAISE EXCEPTION 'Workspace data is busy; retry' USING ERRCODE='55006'; END IF;
 SELECT * INTO intent FROM dation_private.dataset_deletions WHERE dataset_id=target_dataset_id AND workspace_id=target_workspace_id FOR UPDATE;
 IF FOUND AND intent.status='completed' THEN RETURN jsonb_build_object('deleted',true); END IF;
 SELECT * INTO target FROM datasets WHERE id=target_dataset_id AND workspace_id=target_workspace_id FOR UPDATE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'Dataset not found' USING ERRCODE='P0002'; END IF;
 IF target.archived_at IS NULL OR target.is_default OR dation_private.dataset_referenced(target_workspace_id,target_dataset_id) THEN
  RAISE EXCEPTION 'Archive first; referenced datasets must be retained' USING ERRCODE='22023'; END IF;
 IF operation='prepare' THEN
  IF intent.id IS NULL THEN
   INSERT INTO dation_private.dataset_deletions(workspace_id,dataset_id,actor_user_id,storage_bucket,storage_path)
    VALUES(target_workspace_id,target_dataset_id,actor_user_id,target.storage_bucket,target.storage_path) RETURNING * INTO intent;
   UPDATE datasets SET deletion_requested_at=clock_timestamp() WHERE id=target_dataset_id AND workspace_id=target_workspace_id;
  END IF;
  RETURN jsonb_build_object('deleted',false,'operation_id',intent.id,'storage_bucket',intent.storage_bucket,'storage_path',intent.storage_path);
 END IF;
 IF intent.id IS NULL OR operation_id IS DISTINCT FROM intent.id OR target.deletion_requested_at IS NULL THEN
  RAISE EXCEPTION 'Prepare deletion before finishing' USING ERRCODE='42501'; END IF;
 DELETE FROM datasets WHERE id=target_dataset_id AND workspace_id=target_workspace_id;
 UPDATE dation_private.dataset_deletions SET status='completed',completed_at=clock_timestamp() WHERE id=intent.id;
 RETURN jsonb_build_object('deleted',true);
EXCEPTION WHEN lock_not_available THEN
 RAISE EXCEPTION 'Dataset is busy; retry' USING ERRCODE='55006';
END; $function$

CREATE OR REPLACE FUNCTION public.platform_dataset_upload(target_workspace_id uuid, actor_user_id uuid, operation text, target_dataset_id uuid DEFAULT NULL::uuid, operation_id uuid DEFAULT NULL::uuid, object_bucket text DEFAULT NULL::text, object_path text DEFAULT NULL::text, filename text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE intent dation_private.dataset_uploads; stored datasets;
BEGIN
 PERFORM dation_private.data_actor(target_workspace_id,actor_user_id,true);
 IF operation NOT IN('prepare','stored','failed','discard','finish') THEN RAISE EXCEPTION 'Invalid upload operation' USING ERRCODE='22023'; END IF;
 IF operation<>'prepare' AND NOT pg_try_advisory_xact_lock(hashtextextended('dation-data:'||target_workspace_id::text,0)) THEN
  RAISE EXCEPTION 'Workspace data is busy; retry' USING ERRCODE='55006'; END IF;
 IF operation='prepare' THEN
  IF target_dataset_id IS NULL OR length(coalesce(filename,'')) NOT BETWEEN 1 AND 512 OR
   object_bucket IS NULL OR object_path IS NULL OR split_part(object_path,'/',1)<>target_workspace_id::text
   OR split_part(object_path,'/',2)<>target_dataset_id::text OR array_length(string_to_array(object_path,'/'),1)<>3
   OR split_part(object_path,'/',3) IN('','.','..') THEN RAISE EXCEPTION 'Invalid upload identity' USING ERRCODE='22023'; END IF;
  INSERT INTO dation_private.dataset_uploads(workspace_id,actor_user_id,dataset_id,storage_bucket,storage_path,filename)
   VALUES(target_workspace_id,actor_user_id,target_dataset_id,object_bucket,object_path,filename) RETURNING * INTO intent;
  RETURN jsonb_build_object('operation_id',intent.id);
 END IF;
 SELECT * INTO intent FROM dation_private.dataset_uploads WHERE id=operation_id AND workspace_id=target_workspace_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Upload not found' USING ERRCODE='P0002'; END IF;
 SELECT * INTO stored FROM datasets WHERE id=intent.dataset_id AND workspace_id=target_workspace_id;
 IF FOUND THEN
  IF stored.storage_bucket<>intent.storage_bucket OR stored.storage_path<>intent.storage_path THEN RAISE EXCEPTION 'Upload identity mismatch' USING ERRCODE='42501'; END IF;
  UPDATE dation_private.dataset_uploads SET status='stored',updated_at=clock_timestamp() WHERE id=intent.id;
  RETURN jsonb_build_object('cleared',true,'stored',true);
 END IF;
 IF intent.status IN('stored','discarded') THEN RETURN jsonb_build_object('cleared',true); END IF;
 IF operation='stored' THEN RAISE EXCEPTION 'Stored dataset not found' USING ERRCODE='P0002'; END IF;
 IF operation='failed' THEN
  IF intent.status='pending' THEN UPDATE dation_private.dataset_uploads SET status='failed',updated_at=clock_timestamp() WHERE id=intent.id; END IF;
  RETURN jsonb_build_object('pending',true);
 END IF;
 IF operation='finish' THEN
  UPDATE dation_private.dataset_uploads SET status='discarded',updated_at=clock_timestamp() WHERE id=intent.id;
  RETURN jsonb_build_object('cleared',true);
 END IF;
 IF intent.status='pending' AND intent.created_at>now()-interval '15 minutes' THEN
  RAISE EXCEPTION 'Upload is still active' USING ERRCODE='55006'; END IF;
 UPDATE dation_private.dataset_uploads SET status='discarding',updated_at=clock_timestamp() WHERE id=intent.id;
 RETURN jsonb_build_object('cleared',false,'operation_id',intent.id,'dataset_id',intent.dataset_id,
  'storage_bucket',intent.storage_bucket,'storage_path',intent.storage_path);
END; $function$

CREATE OR REPLACE FUNCTION public.platform_decision_center(target_workspace_id uuid, actor_user_id uuid, target_case_id uuid DEFAULT NULL::uuid, filter_name text DEFAULT 'all'::text, search_text text DEFAULT ''::text, dda text DEFAULT 'all'::text, target_node_id text DEFAULT NULL::text, page_limit integer DEFAULT 25, page_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE current_case decision_cases; answer jsonb; history jsonb;
BEGIN
 PERFORM dation_private.data_actor(target_workspace_id,actor_user_id);
 PERFORM set_config('dation.workspace_id',target_workspace_id::text,true);
 IF filter_name NOT IN('all','in_progress','review','completed','archived') OR dda NOT IN('all','logistics')
 OR length(search_text)>120 OR page_limit NOT BETWEEN 1 AND 50 OR page_offset NOT BETWEEN 0 AND 1000000
 OR (target_node_id IS NOT NULL AND target_node_id NOT IN('logistics_assignment','logistics_scheduling','logistics_final_assignment')) THEN
  RAISE EXCEPTION 'Invalid center query' USING ERRCODE='22023'; END IF;
 IF target_case_id IS NOT NULL THEN
  SELECT * INTO current_case FROM decision_cases WHERE id=target_case_id AND workspace_id=target_workspace_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Case not found' USING ERRCODE='P0002'; END IF;
  answer=dation_private.center_bundle(current_case)||jsonb_build_object('collaboration',dation_private.case_collaboration(target_workspace_id,current_case.id,actor_user_id));
  IF target_node_id IS NOT NULL THEN
   SELECT coalesce(jsonb_agg(dation_private.center_run(r) ORDER BY r.created_at DESC,r.id DESC),'[]') INTO history
   FROM (SELECT * FROM decision_runs WHERE workspace_id=target_workspace_id AND decision_case_id=current_case.id AND node_id=target_node_id AND (search_text='' OR id::text=search_text)
     ORDER BY created_at DESC,id DESC LIMIT page_limit OFFSET page_offset) r;
   RETURN answer||jsonb_build_object('runs',history,'node_id',target_node_id,'limit',page_limit,'offset',page_offset);
  END IF;
  RETURN answer||jsonb_build_object('orders',(SELECT dation_private.hub_dataset(d) FROM datasets d WHERE id=current_case.orders_dataset_id AND workspace_id=target_workspace_id),
   'fleet',(SELECT dation_private.hub_dataset(d) FROM datasets d WHERE id=current_case.fleet_dataset_id AND workspace_id=target_workspace_id),
   'run_people',coalesce((SELECT jsonb_object_agg(r.id::text,dation_private.center_run(r)) FROM decision_runs r
    WHERE r.workspace_id=target_workspace_id AND r.decision_case_id=current_case.id AND r.id IN
     (SELECT (value->k->>'id')::uuid FROM jsonb_each(answer->'summaries') CROSS JOIN (VALUES('latest'),('approved')) v(k))),'{}'));
 END IF;
 WITH base AS MATERIALIZED (SELECT c.*,(dation_private.center_bundle(c)||jsonb_build_object('collaboration',dation_private.case_collaboration(target_workspace_id,c.id,actor_user_id))) bundle FROM decision_cases c WHERE c.workspace_id=target_workspace_id
  AND (dda='all' OR c.domain=dda) AND (search_text='' OR strpos(lower(concat_ws(' ',c.id::text,'DC-'||substr(c.id::text,1,8),c.label)),lower(search_text))>0)),
 matched AS (SELECT * FROM base WHERE CASE filter_name
  WHEN 'all' THEN bundle->>'status'<>'archived'
  WHEN 'archived' THEN bundle->>'status'='archived'
  WHEN 'completed' THEN bundle->>'status'='completed'
  WHEN 'review' THEN (bundle->>'in_review')::boolean
  ELSE bundle->>'status'='active' AND NOT (bundle->>'in_review')::boolean END),
 page AS (SELECT * FROM matched ORDER BY last_activity_at DESC,id DESC LIMIT page_limit OFFSET page_offset)
 SELECT jsonb_build_object('items',coalesce((SELECT jsonb_agg(bundle ORDER BY last_activity_at DESC,id DESC) FROM page),'[]'),
  'total',(SELECT count(*) FROM matched),'limit',page_limit,'offset',page_offset) INTO answer;
 RETURN answer;
END; $function$

CREATE OR REPLACE FUNCTION public.platform_identity(actor_user_id uuid, first_name text DEFAULT ''::text, last_name text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE account auth.users; person profiles; membership workspace_members; workspace workspaces; legacy record; membership_count integer;
BEGIN
 IF NOT (SELECT admissions_open FROM dation_private.platform_release WHERE singleton) THEN RAISE EXCEPTION 'Platform access is being upgraded' USING ERRCODE='55000'; END IF;
 SELECT * INTO account FROM auth.users WHERE id=actor_user_id AND email_confirmed_at IS NOT NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'Confirmed identity required' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(actor_user_id::text,0));
 INSERT INTO profiles(id,first_name,last_name,display_name) VALUES(actor_user_id,left(first_name,100),left(last_name,100),trim(left(first_name,100)||' '||left(last_name,100)))
 ON CONFLICT(id) DO NOTHING;
 -- Only a confirmed, explicitly authorized email can claim the preserved workspace.
 FOR legacy IN SELECT * FROM dation_private.legacy_owners WHERE email=lower(account.email) AND claimed_by IS NULL FOR UPDATE LOOP
  INSERT INTO workspace_members(workspace_id,user_id,access_role,status,joined_at)
   VALUES(legacy.workspace_id,actor_user_id,'admin','active',now()) ON CONFLICT DO NOTHING;
  UPDATE dation_private.legacy_owners SET claimed_by=actor_user_id WHERE email=legacy.email;
  UPDATE workspaces SET created_by=actor_user_id,updated_at=now() WHERE id=legacy.workspace_id AND created_by IS NULL;
  UPDATE profiles SET active_workspace_id=legacy.workspace_id WHERE id=actor_user_id;
  INSERT INTO audit_events(workspace_id,actor_user_id,event_type) VALUES(legacy.workspace_id,actor_user_id,'workspace.legacy_claimed');
 END LOOP;
 SELECT * INTO person FROM profiles WHERE id=actor_user_id;
 SELECT count(*) INTO membership_count FROM workspace_members m JOIN workspaces w ON w.id=m.workspace_id
  WHERE m.user_id=actor_user_id AND m.status='active' AND w.status='active';
 IF membership_count=1 THEN
  SELECT m.* INTO membership FROM workspace_members m JOIN workspaces w ON w.id=m.workspace_id
   WHERE m.user_id=actor_user_id AND m.status='active' AND w.status='active';
 ELSIF membership_count>1 THEN
  SELECT m.* INTO membership FROM workspace_members m JOIN workspaces w ON w.id=m.workspace_id
   WHERE m.user_id=actor_user_id AND m.workspace_id=person.active_workspace_id AND m.status='active' AND w.status='active';
  IF NOT FOUND THEN RAISE EXCEPTION 'Multiple memberships require an administrator-selected active workspace' USING ERRCODE='42501'; END IF;
 ELSIF EXISTS(SELECT 1 FROM workspace_members WHERE user_id=actor_user_id) THEN
  RAISE EXCEPTION 'No active membership' USING ERRCODE='42501';
 END IF;
 IF membership.workspace_id IS NOT NULL THEN
  SELECT * INTO workspace FROM workspaces WHERE id=membership.workspace_id;
 END IF;
 RETURN jsonb_build_object('profile',to_jsonb(person)||jsonb_build_object('email',account.email),
   'membership',CASE WHEN membership.workspace_id IS NULL THEN NULL ELSE to_jsonb(membership) END,
   'workspace',CASE WHEN workspace.id IS NULL THEN NULL ELSE to_jsonb(workspace) END,
   'ddas',coalesce((SELECT jsonb_agg(to_jsonb(d)) FROM workspace_ddas d WHERE d.workspace_id=membership.workspace_id),'[]'));
END; $function$

CREATE OR REPLACE FUNCTION public.platform_invite_member(target_workspace_id uuid, actor_user_id uuid, invite_email text, invite_role text, invite_business_role text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE invitation workspace_invitations;
BEGIN
 PERFORM 1 FROM workspaces WHERE id=target_workspace_id FOR UPDATE;
 PERFORM dation_private.team_actor(target_workspace_id,actor_user_id,true);
 IF invite_email IS NULL OR invite_role IS NULL OR invite_email<>lower(trim(invite_email)) OR length(invite_email)>254 OR invite_email !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$'
 OR invite_role NOT IN('admin','operator','viewer') OR (invite_business_role IS NOT NULL AND invite_business_role NOT IN('data_owner','data_steward','decision_owner','approver')) THEN RAISE EXCEPTION 'Invalid invitation' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM workspace_members m JOIN auth.users u ON u.id=m.user_id WHERE m.workspace_id=target_workspace_id AND lower(u.email)=invite_email) THEN
 RAISE EXCEPTION 'Member already exists; manage the member instead' USING ERRCODE='22023'; END IF;
 -- Revoke expired invitations before issuing a fresh one; active duplicates fail.
 UPDATE workspace_invitations SET status='revoked',updated_at=clock_timestamp() WHERE workspace_id=target_workspace_id AND email=invite_email AND status='pending' AND expires_at<=now();
 IF EXISTS(SELECT 1 FROM workspace_invitations WHERE workspace_id=target_workspace_id AND email=invite_email AND status='pending') THEN RAISE EXCEPTION 'Invitation already pending' USING ERRCODE='22023'; END IF;
 INSERT INTO workspace_invitations(workspace_id,email,access_role,business_role,invited_by) VALUES(target_workspace_id,invite_email,invite_role,invite_business_role,actor_user_id) RETURNING * INTO invitation;
 INSERT INTO audit_events(workspace_id,actor_user_id,event_type,metadata_json) VALUES(target_workspace_id,actor_user_id,'team.invited',jsonb_build_object('invitation_id',invitation.id,'email',invite_email,'access_role',invite_role,'business_role',invite_business_role));
 RETURN jsonb_build_object('id',invitation.id,'email',invitation.email,'expires_at',invitation.expires_at,'updated_at',invitation.updated_at);
END; $function$

CREATE OR REPLACE FUNCTION public.platform_onboarding(target_workspace_id uuid, actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE explored timestamptz; enabled boolean; prepared boolean=false; first_run decision_runs;
BEGIN
 PERFORM dation_private.team_actor(target_workspace_id,actor_user_id);
 SELECT explored_at INTO explored FROM dation_private.workspace_onboarding
 WHERE workspace_id=target_workspace_id AND user_id=actor_user_id;
 SELECT EXISTS(SELECT 1 FROM workspace_ddas WHERE workspace_id=target_workspace_id AND dda_id='logistics' AND status='enabled') INTO enabled;
 IF enabled THEN
  SELECT EXISTS(SELECT 1 FROM datasets WHERE workspace_id=target_workspace_id AND dataset_type='orders' AND archived_at IS NULL AND deletion_requested_at IS NULL AND profile_json->'valid'='true')
   AND EXISTS(SELECT 1 FROM datasets WHERE workspace_id=target_workspace_id AND dataset_type='fleet' AND archived_at IS NULL AND deletion_requested_at IS NULL AND profile_json->'valid'='true') INTO prepared;
  SELECT * INTO first_run FROM decision_runs WHERE workspace_id=target_workspace_id AND status='completed' AND node_id IN('logistics_assignment','logistics_scheduling') ORDER BY created_at,id LIMIT 1;
 END IF;
 RETURN jsonb_build_object('available',true,'workspace_created',true,'explored_at',explored,'data_ready',prepared,
  'first_decision_completed',first_run.id IS NOT NULL,'logistics_enabled',enabled,
  'data_includes_demo',prepared AND EXISTS(SELECT 1 FROM datasets WHERE workspace_id=target_workspace_id AND dataset_type IN('orders','fleet') AND is_sample AND archived_at IS NULL AND deletion_requested_at IS NULL AND profile_json->'valid'='true'),
  'first_decision_demo',EXISTS(SELECT 1 FROM datasets WHERE workspace_id=target_workspace_id AND is_sample AND id IN(first_run.orders_dataset_id,first_run.fleet_dataset_id,first_run.dataset_id)));
END; $function$

CREATE OR REPLACE FUNCTION public.platform_received_invitations(actor_user_id uuid, invitation_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE account auth.users; invitation workspace_invitations; member workspace_members;
BEGIN
 IF NOT coalesce((SELECT admissions_open FROM dation_private.platform_release WHERE singleton),false) THEN RAISE EXCEPTION 'Admissions closed' USING ERRCODE='42501'; END IF;
 SELECT * INTO account FROM auth.users WHERE id=actor_user_id AND email_confirmed_at IS NOT NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'Confirmed identity required' USING ERRCODE='42501'; END IF;
 IF invitation_id IS NULL THEN
 RETURN jsonb_build_object('items',coalesce((SELECT jsonb_agg(to_jsonb(i)) FROM (
 SELECT i.id,w.name AS workspace_name,i.access_role,i.business_role,i.expires_at FROM workspace_invitations i JOIN workspaces w ON w.id=i.workspace_id
 WHERE i.email=lower(account.email) AND i.status='pending' AND i.expires_at>now() AND w.status='active'
 AND EXISTS(SELECT 1 FROM workspace_members m WHERE m.workspace_id=i.workspace_id AND m.user_id=i.invited_by AND m.status='active' AND m.access_role='admin')
 ORDER BY i.created_at DESC,i.id LIMIT 50) i),'[]'));
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(actor_user_id::text,0));
 SELECT * INTO invitation FROM workspace_invitations WHERE id=invitation_id AND email=lower(account.email);
 IF NOT FOUND THEN RAISE EXCEPTION 'Invitation not found' USING ERRCODE='P0002'; END IF;
 PERFORM 1 FROM workspaces WHERE id=invitation.workspace_id AND status='active' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Workspace unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO invitation FROM workspace_invitations WHERE id=invitation_id FOR UPDATE;
 IF invitation.status='accepted' AND invitation.accepted_by=actor_user_id THEN
 PERFORM dation_private.team_actor(invitation.workspace_id,actor_user_id);
 RETURN jsonb_build_object('workspace_id',invitation.workspace_id,'already_accepted',true);
 END IF;
 IF invitation.status<>'pending' OR invitation.expires_at<=now() THEN RAISE EXCEPTION 'Invitation expired or revoked' USING ERRCODE='22023'; END IF;
 PERFORM dation_private.team_actor(invitation.workspace_id,invitation.invited_by,true);
 IF EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=invitation.workspace_id AND user_id=actor_user_id) THEN RAISE EXCEPTION 'Existing member cannot accept an invitation' USING ERRCODE='22023'; END IF;
 INSERT INTO profiles(id) VALUES(actor_user_id) ON CONFLICT DO NOTHING;
 INSERT INTO workspace_members(workspace_id,user_id,access_role,business_role,invited_by,joined_at)
 VALUES(invitation.workspace_id,actor_user_id,invitation.access_role,invitation.business_role,invitation.invited_by,clock_timestamp());
 UPDATE profiles SET active_workspace_id=invitation.workspace_id,updated_at=clock_timestamp() WHERE id=actor_user_id;
 UPDATE workspace_invitations SET status='accepted',accepted_by=actor_user_id,accepted_at=clock_timestamp(),updated_at=clock_timestamp() WHERE id=invitation_id;
 INSERT INTO audit_events(workspace_id,actor_user_id,event_type,metadata_json) VALUES(invitation.workspace_id,actor_user_id,'team.invitation_accepted',jsonb_build_object('invitation_id',invitation_id,'access_role',invitation.access_role,'business_role',invitation.business_role));
 RETURN jsonb_build_object('workspace_id',invitation.workspace_id,'already_accepted',false);
END; $function$

CREATE OR REPLACE FUNCTION public.platform_record_export(target_workspace_id uuid, actor_user_id uuid, target_run_id uuid, export_format text, operation_id uuid, content_sha256 text, content_bytes integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r decision_runs; previous audit_events; key text;
BEGIN
 PERFORM dation_private.team_actor(target_workspace_id,actor_user_id);
 IF NOT EXISTS(SELECT 1 FROM workspace_ddas WHERE workspace_id=target_workspace_id AND dda_id='logistics' AND status='enabled') THEN RAISE EXCEPTION 'DDA not enabled' USING ERRCODE='42501'; END IF;
 SELECT * INTO r FROM decision_runs WHERE id=target_run_id AND workspace_id=target_workspace_id AND status='completed';
 IF NOT FOUND THEN RAISE EXCEPTION 'Exportable run not found' USING ERRCODE='P0002'; END IF;
 IF export_format IS NULL OR export_format NOT IN('csv','json') OR operation_id IS NULL OR content_sha256 IS NULL OR content_sha256 !~ '^[a-f0-9]{64}$' OR content_bytes IS NULL OR content_bytes<1 THEN RAISE EXCEPTION 'Invalid export' USING ERRCODE='22023'; END IF;
 key='export:'||actor_user_id::text||':'||operation_id::text;
 INSERT INTO audit_events(workspace_id,actor_user_id,event_type,object_type,object_id,decision_case_id,node_id,event_key,metadata_json)
 VALUES(target_workspace_id,actor_user_id,'export.generated','run',r.id,r.decision_case_id,r.node_id,key,
  jsonb_build_object('format',export_format,'bytes',content_bytes,'sha256',content_sha256)) ON CONFLICT(workspace_id,event_key) WHERE event_key IS NOT NULL DO NOTHING;
 SELECT * INTO previous FROM audit_events WHERE workspace_id=target_workspace_id AND event_key=key;
 IF previous.object_id<>r.id OR previous.metadata_json->>'format'<>export_format OR previous.metadata_json->>'sha256'<>content_sha256 THEN RAISE EXCEPTION 'Export request changed' USING ERRCODE='55006'; END IF;
 RETURN jsonb_build_object('id',previous.id);
END; $function$

CREATE OR REPLACE FUNCTION public.platform_replace_case_data_pack(target_workspace_id uuid, actor_user_id uuid, target_case_id uuid, expected_updated_at timestamp with time zone, orders_id uuid, fleet_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE c decision_cases; next_case decision_cases; next_id uuid;
BEGIN
 PERFORM dation_private.data_actor(target_workspace_id,actor_user_id,true);
 PERFORM set_config('dation.workspace_id',target_workspace_id::text,true);
 PERFORM set_config('dation.actor_user_id',actor_user_id::text,true);
 PERFORM 1 FROM workspaces WHERE id=target_workspace_id FOR UPDATE;
 SELECT * INTO c FROM decision_cases WHERE workspace_id=target_workspace_id AND id=target_case_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Case not found' USING ERRCODE='P0002'; END IF;
 IF expected_updated_at IS DISTINCT FROM c.updated_at THEN RAISE EXCEPTION 'Case changed; refresh' USING ERRCODE='55006'; END IF;
 IF NOT EXISTS(SELECT 1 FROM datasets WHERE workspace_id=target_workspace_id AND id=orders_id AND dataset_type='orders' AND deletion_requested_at IS NULL)
 OR NOT EXISTS(SELECT 1 FROM datasets WHERE workspace_id=target_workspace_id AND id=fleet_id AND dataset_type='fleet' AND deletion_requested_at IS NULL) THEN
  RAISE EXCEPTION 'Invalid Data Pack' USING ERRCODE='22023'; END IF;
 IF (c.orders_dataset_id,c.fleet_dataset_id)=(orders_id,fleet_id) THEN
  RETURN jsonb_build_object('id',c.id,'updated_at',c.updated_at,'created',false);
 END IF;
 -- Stable per source Case/Data Pack so a network retry cannot duplicate the fork.
 next_id=md5(target_workspace_id::text||target_case_id::text||orders_id::text||fleet_id::text)::uuid;
 INSERT INTO decision_cases(id,workspace_id,schema_version,domain,status,orders_dataset_id,fleet_dataset_id,input_signature,label,category,description,state_json)
 VALUES(next_id,target_workspace_id,'decision_case_v2',c.domain,'active',orders_id,fleet_id,orders_id::text||':'||fleet_id::text,c.label,c.category,c.description,'{}'::jsonb)
 ON CONFLICT(id) DO NOTHING;
 SELECT * INTO STRICT next_case FROM decision_cases WHERE workspace_id=target_workspace_id AND id=next_id
  AND orders_dataset_id=orders_id AND fleet_dataset_id=fleet_id;
 RETURN jsonb_build_object('id',next_case.id,'updated_at',next_case.updated_at,'created',true,'predecessor_id',c.id);
END; $function$

CREATE OR REPLACE FUNCTION public.platform_revoke_invitation(target_workspace_id uuid, actor_user_id uuid, invitation_id uuid, expected_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE invitation workspace_invitations;
BEGIN
 PERFORM 1 FROM workspaces WHERE id=target_workspace_id FOR UPDATE;
 PERFORM dation_private.team_actor(target_workspace_id,actor_user_id,true);
 SELECT * INTO invitation FROM workspace_invitations WHERE workspace_id=target_workspace_id AND id=invitation_id FOR UPDATE;
