CREATE OR REPLACE FUNCTION public.platform_rpc(target_workspace_id uuid, actor_user_id uuid, operation text, arguments jsonb DEFAULT '{}'::jsonb, worker_call boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE member_role text; answer jsonb; payload jsonb; is_read boolean;
BEGIN
 IF target_workspace_id IS NULL OR jsonb_typeof(arguments) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Invalid context' USING ERRCODE='42501'; END IF;
 PERFORM set_config('dation.workspace_id',target_workspace_id::text,true);
 PERFORM set_config('dation.actor_user_id',coalesce(actor_user_id::text,''),true);
 is_read=operation IN('list_decision_cases','decision_case_history','read_decision_chat_turn','read_decision_chat_turn_with_evidence','current_decision_explanation',
  'dispatch_operational_snapshot','comparative_operational_snapshot');
 IF worker_call THEN
  IF actor_user_id IS NOT NULL OR operation NOT IN('heartbeat_dispatch_job','finish_dispatch_job','heartbeat_comparative_analysis','finish_comparative_analysis','ack_case_reconciliation','decision_case_history') THEN
   RAISE EXCEPTION 'Worker operation denied' USING ERRCODE='42501'; END IF;
 ELSE
  SELECT m.access_role INTO member_role FROM workspace_members m JOIN workspaces w ON w.id=m.workspace_id
   WHERE m.workspace_id=target_workspace_id AND m.user_id=actor_user_id AND m.status='active' AND w.status='active';
  IF NOT FOUND OR (member_role='viewer' AND NOT is_read) THEN RAISE EXCEPTION 'Membership denied' USING ERRCODE='42501'; END IF;
  IF operation IN('dispatch_operational_snapshot','comparative_operational_snapshot') AND member_role<>'admin' THEN RAISE EXCEPTION 'Admin required' USING ERRCODE='42501'; END IF;
 END IF;
 PERFORM dation_private.assert_owned('decision_runs',(arguments->>'target_run_id')::uuid,target_workspace_id);
 PERFORM dation_private.assert_owned('decision_cases',(arguments->>'target_case_id')::uuid,target_workspace_id);
 PERFORM dation_private.assert_owned('decision_runs',(arguments->>'target_base_id')::uuid,target_workspace_id);
 PERFORM dation_private.assert_owned('decision_comparative_analyses',(arguments->>'target_analysis_id')::uuid,target_workspace_id);
 PERFORM dation_private.assert_owned('datasets',(arguments->>'target_id')::uuid,target_workspace_id);
 PERFORM dation_private.assert_owned('decision_chat_turns',(arguments->>'target_turn_id')::uuid,target_workspace_id,true);
 PERFORM dation_private.assert_owned('decision_comparative_analyses',(arguments->>'evidence_analysis_id')::uuid,target_workspace_id);
 IF arguments ? 'explanation' THEN
  PERFORM dation_private.assert_owned('decision_runs',(arguments->'explanation'->>'run_id')::uuid,target_workspace_id);
  PERFORM dation_private.assert_owned('decision_explanations',(arguments->'explanation'->>'id')::uuid,target_workspace_id,true);
 END IF;
 IF operation='enqueue_dispatch_run' THEN
  payload=arguments->'run_payload';
  PERFORM dation_private.assert_owned('decision_runs',(payload->>'id')::uuid,target_workspace_id,true);
  PERFORM dation_private.check_json_references(payload-'id',target_workspace_id);
  IF arguments->'job_request'->>'workspace_id' IS DISTINCT FROM target_workspace_id::text THEN RAISE EXCEPTION 'Invalid job workspace' USING ERRCODE='42501'; END IF;
 END IF;
 CASE operation
 WHEN 'list_decision_cases' THEN SELECT coalesce(jsonb_agg(to_jsonb(result)),'[]') INTO answer FROM dation_private.list_decision_cases(coalesce((arguments->>'case_status')::text,'active'),coalesce((arguments->>'page_limit')::integer,50),coalesce((arguments->>'page_offset')::integer,0),coalesce((arguments->>'summary_only')::boolean,false)) result;
 WHEN 'decision_case_history' THEN SELECT to_jsonb(dation_private.decision_case_history((arguments->>'target_case_id')::uuid,(arguments->>'target_node_id')::text,coalesce((arguments->>'page_limit')::integer,50),coalesce((arguments->>'page_offset')::integer,0))) INTO answer;
 WHEN 'approve_decision_run_version' THEN SELECT coalesce(jsonb_agg(to_jsonb(result)),'[]') INTO answer FROM dation_private.approve_decision_run_version((arguments->>'target_run_id')::uuid,(arguments->>'target_case_id')::uuid,(arguments->>'target_node_id')::text) result;
 WHEN 'enqueue_dispatch_run' THEN SELECT coalesce(jsonb_agg(to_jsonb(result)),'[]') INTO answer FROM dation_private.enqueue_dispatch_run(nullif(arguments->'run_payload','null'::jsonb),nullif(arguments->'job_request','null'::jsonb),(arguments->>'intent_fingerprint')::text,coalesce((arguments->>'queue_limit')::integer,32)) result;
 WHEN 'cancel_dispatch_job' THEN SELECT coalesce(jsonb_agg(to_jsonb(result)),'[]') INTO answer FROM dation_private.cancel_dispatch_job((arguments->>'target_run_id')::uuid) result;
 WHEN 'heartbeat_dispatch_job' THEN SELECT to_jsonb(dation_private.heartbeat_dispatch_job((arguments->>'target_run_id')::uuid,(arguments->>'worker_token')::uuid,coalesce((arguments->>'lease_seconds')::integer,120),nullif(arguments->'progress','null'::jsonb))) INTO answer;
 WHEN 'finish_dispatch_job' THEN SELECT coalesce(jsonb_agg(to_jsonb(result)),'[]') INTO answer FROM dation_private.finish_dispatch_job((arguments->>'target_run_id')::uuid,(arguments->>'worker_token')::uuid,nullif(arguments->'terminal_values','null'::jsonb)) result;
 WHEN 'ack_case_reconciliation' THEN PERFORM dation_private.ack_case_reconciliation((arguments->>'target_case_id')::uuid,(arguments->>'observed_version')::bigint); answer='null'::jsonb;
 WHEN 'request_case_reconciliation' THEN PERFORM dation_private.request_case_reconciliation((arguments->>'target_case_id')::uuid); answer='null'::jsonb;
 WHEN 'set_default_fleet' THEN PERFORM dation_private.set_default_fleet((arguments->>'target_id')::uuid); answer='null'::jsonb;
 WHEN 'enqueue_comparative_analysis' THEN SELECT coalesce(jsonb_agg(to_jsonb(result)),'[]') INTO answer FROM dation_private.enqueue_comparative_analysis((arguments->>'target_base_id')::uuid,nullif(arguments->'job_request','null'::jsonb),nullif(arguments->'existing_result','null'::jsonb),coalesce((arguments->>'retry_failed')::boolean,false)) result;
 WHEN 'heartbeat_comparative_analysis' THEN SELECT to_jsonb(dation_private.heartbeat_comparative_analysis((arguments->>'target_analysis_id')::uuid,(arguments->>'worker_token')::uuid,coalesce((arguments->>'lease_seconds')::integer,120),nullif(arguments->'progress','null'::jsonb))) INTO answer;
 WHEN 'finish_comparative_analysis' THEN SELECT coalesce(jsonb_agg(to_jsonb(result)),'[]') INTO answer FROM dation_private.finish_comparative_analysis((arguments->>'target_analysis_id')::uuid,(arguments->>'worker_token')::uuid,nullif(arguments->'terminal_values','null'::jsonb)) result;
 WHEN 'read_decision_chat_turn' THEN SELECT to_jsonb(dation_private.read_decision_chat_turn((arguments->>'target_turn_id')::uuid,(arguments->>'target_run_id')::uuid,(arguments->>'intent_hash')::text)) INTO answer;
 WHEN 'read_decision_chat_turn_with_evidence' THEN SELECT to_jsonb(dation_private.read_decision_chat_turn_with_evidence((arguments->>'target_turn_id')::uuid,(arguments->>'target_run_id')::uuid,(arguments->>'intent_hash')::text)) INTO answer;
 WHEN 'record_decision_chat_turn' THEN SELECT to_jsonb(dation_private.record_decision_chat_turn((arguments->>'target_turn_id')::uuid,(arguments->>'target_run_id')::uuid,(arguments->>'intent_hash')::text,(arguments->>'question_text')::text,(arguments->>'answer_text')::text,nullif(arguments->'metadata','null'::jsonb))) INTO answer;
 WHEN 'record_decision_chat_turn_with_evidence' THEN SELECT to_jsonb(dation_private.record_decision_chat_turn_with_evidence((arguments->>'target_turn_id')::uuid,(arguments->>'target_run_id')::uuid,(arguments->>'intent_hash')::text,(arguments->>'question_text')::text,(arguments->>'answer_text')::text,nullif(arguments->'metadata','null'::jsonb),(arguments->>'evidence_analysis_id')::uuid)) INTO answer;
 WHEN 'record_decision_explanation_with_evidence' THEN SELECT coalesce(jsonb_agg(to_jsonb(result)),'[]') INTO answer FROM dation_private.record_decision_explanation_with_evidence(nullif(arguments->'explanation','null'::jsonb),(arguments->>'evidence_analysis_id')::uuid) result;
 WHEN 'current_decision_explanation' THEN SELECT coalesce(jsonb_agg(to_jsonb(result)),'[]') INTO answer FROM dation_private.current_decision_explanation((arguments->>'target_run_id')::uuid) result;
 WHEN 'dispatch_operational_snapshot' THEN SELECT to_jsonb(dation_private.dispatch_operational_snapshot()) INTO answer;
 WHEN 'comparative_operational_snapshot' THEN SELECT to_jsonb(dation_private.comparative_operational_snapshot()) INTO answer;
 ELSE RAISE EXCEPTION 'Operation denied' USING ERRCODE='42501';
 END CASE;
 RETURN answer;
END; $function$

CREATE OR REPLACE FUNCTION public.platform_set_member_responsibilities(target_workspace_id uuid, actor_user_id uuid, member_user_id uuid, expected_updated_at timestamp with time zone, new_responsibilities text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE member public.workspace_members; roles text[]; previous text[];
BEGIN
 PERFORM 1 FROM public.workspaces WHERE id=target_workspace_id FOR UPDATE;
 PERFORM dation_private.team_actor(target_workspace_id,actor_user_id,true);
 SELECT * INTO member FROM public.workspace_members WHERE workspace_id=target_workspace_id AND user_id=member_user_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Member not found' USING ERRCODE='P0002'; END IF;
 IF expected_updated_at IS NULL OR member.updated_at IS DISTINCT FROM expected_updated_at THEN RAISE EXCEPTION 'Member changed' USING ERRCODE='55006'; END IF;
 IF new_responsibilities IS NULL OR cardinality(new_responsibilities)>4 OR array_position(new_responsibilities,NULL) IS NOT NULL OR NOT new_responsibilities <@ ARRAY['data_owner','data_steward','decision_owner','approver'] THEN RAISE EXCEPTION 'Invalid responsibilities' USING ERRCODE='22023'; END IF;
 SELECT coalesce(array_agg(DISTINCT value ORDER BY value),'{}') INTO roles FROM unnest(new_responsibilities) t(value);
 IF cardinality(roles)<>cardinality(new_responsibilities) THEN RAISE EXCEPTION 'Duplicate responsibility' USING ERRCODE='22023'; END IF;
 previous=dation_private.member_roles(target_workspace_id,member_user_id);
 IF roles=previous THEN RETURN jsonb_build_object('business_roles',roles,'updated_at',member.updated_at); END IF;
 UPDATE public.workspace_members SET business_role=roles[1],updated_at=clock_timestamp() WHERE workspace_id=target_workspace_id AND user_id=member_user_id RETURNING * INTO member;
 DELETE FROM dation_private.member_responsibilities WHERE workspace_id=target_workspace_id AND user_id=member_user_id;
 INSERT INTO dation_private.member_responsibilities SELECT target_workspace_id,member_user_id,value FROM unnest(roles) t(value);
 INSERT INTO public.audit_events(workspace_id,actor_user_id,event_type,object_type,object_id,metadata_json) VALUES(target_workspace_id,actor_user_id,'member.responsibilities_changed','member',member_user_id,jsonb_build_object('user_id',member_user_id,'previous',previous,'responsibilities',roles));
 RETURN jsonb_build_object('business_roles',roles,'updated_at',member.updated_at);
END; $function$

CREATE OR REPLACE FUNCTION public.platform_team_foundation(target_workspace_id uuid, actor_user_id uuid, search_text text DEFAULT ''::text, page_limit integer DEFAULT 25, page_offset integer DEFAULT 0, candidates_only boolean DEFAULT false, responsibility_group text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE answer jsonb; members jsonb; total bigint;
BEGIN
 PERFORM dation_private.team_actor(target_workspace_id,actor_user_id);
 IF responsibility_group IS NULL THEN
  answer=public.platform_team(target_workspace_id,actor_user_id,search_text,page_limit,page_offset,candidates_only);
  SELECT coalesce(jsonb_agg(value||jsonb_build_object('business_roles',dation_private.member_roles(target_workspace_id,(value->>'user_id')::uuid)) ORDER BY ordinal),'[]') INTO members FROM jsonb_array_elements(answer->'members') WITH ORDINALITY e(value,ordinal);
  RETURN answer||jsonb_build_object('members',members);
 END IF;
 IF NOT candidates_only OR responsibility_group NOT IN('data','data_owner','data_steward','decision_owner','approver') OR search_text IS NULL OR length(search_text)>120 OR page_limit IS NULL OR page_limit NOT BETWEEN 1 AND 50 OR page_offset IS NULL OR page_offset NOT BETWEEN 0 AND 1000000 THEN RAISE EXCEPTION 'Invalid candidates query' USING ERRCODE='22023'; END IF;
 WITH matched AS MATERIALIZED (
  SELECT m.*,u.email,coalesce(nullif(p.display_name,''),'Miembro del equipo') name,dation_private.member_roles(m.workspace_id,m.user_id) business_roles
  FROM public.workspace_members m JOIN auth.users u ON u.id=m.user_id LEFT JOIN public.profiles p ON p.id=m.user_id
  WHERE m.workspace_id=target_workspace_id AND dation_private.responsibility_eligible(target_workspace_id,m.user_id,responsibility_group)
   AND (search_text='' OR strpos(lower(concat_ws(' ',p.display_name,u.email)),lower(search_text))>0)),
 page AS (SELECT * FROM matched ORDER BY name,user_id LIMIT page_limit OFFSET page_offset)
 SELECT coalesce((SELECT jsonb_agg(to_jsonb(p) ORDER BY name,user_id) FROM page p),'[]'),(SELECT count(*) FROM matched) INTO members,total;
 RETURN jsonb_build_object('members',members,'invitations','[]'::jsonb,'total',total,'invitation_total',0,'limit',page_limit,'offset',page_offset);
END; $function$

CREATE OR REPLACE FUNCTION public.platform_update_case(target_workspace_id uuid, actor_user_id uuid, target_case_id uuid, expected_updated_at timestamp with time zone, change_label boolean DEFAULT false, new_label text DEFAULT NULL::text, archive boolean DEFAULT NULL::boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE c decision_cases;
BEGIN
 PERFORM dation_private.data_actor(target_workspace_id,actor_user_id,true);
 SELECT * INTO c FROM decision_cases WHERE workspace_id=target_workspace_id AND id=target_case_id FOR UPDATE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'Case not found' USING ERRCODE='P0002'; END IF;
 IF expected_updated_at IS DISTINCT FROM c.updated_at THEN RAISE EXCEPTION 'Case changed; refresh' USING ERRCODE='55006'; END IF;
 IF change_label AND new_label IS NOT NULL AND (length(trim(new_label)) NOT BETWEEN 1 AND 120) THEN RAISE EXCEPTION 'Invalid label' USING ERRCODE='22023'; END IF;
 UPDATE decision_cases SET label=CASE WHEN change_label THEN nullif(trim(new_label),'') ELSE label END,
  status=CASE WHEN archive THEN 'archived' WHEN archive=false THEN 'active' ELSE status END,
  archived_at=CASE WHEN archive THEN now() WHEN archive=false THEN NULL ELSE archived_at END,
  updated_at=clock_timestamp(),last_activity_at=clock_timestamp() WHERE id=c.id AND workspace_id=target_workspace_id RETURNING * INTO c;
 RETURN jsonb_build_object('id',c.id,'label',c.label,'updated_at',c.updated_at,'status',c.status);
EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION 'Case is busy; retry' USING ERRCODE='55006';
END; $function$

CREATE OR REPLACE FUNCTION public.platform_update_case_identity(target_workspace_id uuid, actor_user_id uuid, target_case_id uuid, expected_updated_at timestamp with time zone, identity_changes jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE c decision_cases; result jsonb;
BEGIN
 IF jsonb_typeof(identity_changes)<>'object' OR identity_changes-'label'-'category'-'description'<>'{}'::jsonb THEN
  RAISE EXCEPTION 'Invalid Case identity' USING ERRCODE='22023';
 END IF;
 -- Reuse the canonical actor, workspace, row lock, name validation and CAS.
 result=public.platform_update_case(target_workspace_id,actor_user_id,target_case_id,expected_updated_at,
  identity_changes?'label',identity_changes->>'label',NULL);
 UPDATE decision_cases SET
  category=CASE WHEN identity_changes?'category' THEN identity_changes->>'category' ELSE category END,
  description=CASE WHEN identity_changes?'description' THEN nullif(trim(identity_changes->>'description'),'') ELSE description END
 WHERE workspace_id=target_workspace_id AND id=target_case_id RETURNING * INTO c;
 RETURN result||jsonb_build_object('category',c.category,'description',c.description);
END; $function$

CREATE OR REPLACE FUNCTION public.platform_update_member(target_workspace_id uuid, actor_user_id uuid, member_user_id uuid, expected_updated_at timestamp with time zone, new_role text, new_business_role text, new_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE member workspace_members;
BEGIN
 PERFORM 1 FROM workspaces WHERE id=target_workspace_id FOR UPDATE;
 PERFORM dation_private.team_actor(target_workspace_id,actor_user_id,true);
 SELECT * INTO member FROM workspace_members WHERE workspace_id=target_workspace_id AND user_id=member_user_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Member not found' USING ERRCODE='P0002'; END IF;
 IF member.updated_at IS DISTINCT FROM expected_updated_at THEN RAISE EXCEPTION 'Member changed' USING ERRCODE='55006'; END IF;
 IF new_role IS NULL OR new_status IS NULL OR new_role NOT IN('admin','operator','viewer') OR new_status NOT IN('active','disabled') OR
 (new_business_role IS NOT NULL AND new_business_role NOT IN('data_owner','data_steward','decision_owner','approver')) THEN RAISE EXCEPTION 'Invalid role' USING ERRCODE='22023'; END IF;
 IF member.access_role='admin' AND member.status='active' AND (new_role<>'admin' OR new_status<>'active') AND NOT EXISTS(
 SELECT 1 FROM workspace_members m JOIN auth.users u ON u.id=m.user_id AND u.email_confirmed_at IS NOT NULL
 WHERE m.workspace_id=target_workspace_id AND m.user_id<>member_user_id AND m.access_role='admin' AND m.status='active') THEN
 RAISE EXCEPTION 'Keep at least one active administrator' USING ERRCODE='22023'; END IF;
 UPDATE workspace_members SET access_role=new_role,business_role=new_business_role,status=new_status,updated_at=clock_timestamp()
 WHERE workspace_id=target_workspace_id AND user_id=member_user_id;
 INSERT INTO audit_events(workspace_id,actor_user_id,event_type,metadata_json) VALUES(target_workspace_id,actor_user_id,'team.member_updated',
 jsonb_build_object('user_id',member_user_id,'before',jsonb_build_object('access_role',member.access_role,'business_role',member.business_role,'status',member.status),'after',jsonb_build_object('access_role',new_role,'business_role',new_business_role,'status',new_status)));
 RETURN jsonb_build_object('user_id',member_user_id,'status',new_status);
END; $function$

CREATE OR REPLACE FUNCTION public.platform_update_member_foundation(target_workspace_id uuid, actor_user_id uuid, member_user_id uuid, expected_updated_at timestamp with time zone, new_role text, new_status text, new_business_roles text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE member public.workspace_members; result jsonb;
BEGIN
 PERFORM 1 FROM public.workspaces WHERE id=target_workspace_id FOR UPDATE;
 PERFORM dation_private.team_actor(target_workspace_id,actor_user_id,true);
 SELECT * INTO member FROM public.workspace_members WHERE workspace_id=target_workspace_id AND user_id=member_user_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Member not found' USING ERRCODE='P0002'; END IF;
 -- Update responsibilities while the actor still has Admin access. This also
 -- allows an Admin to demote themself when another active Admin remains.
 result=public.platform_set_member_responsibilities(target_workspace_id,actor_user_id,member_user_id,expected_updated_at,new_business_roles);
 SELECT * INTO member FROM public.workspace_members WHERE workspace_id=target_workspace_id AND user_id=member_user_id;
 PERFORM public.platform_update_member(target_workspace_id,actor_user_id,member_user_id,member.updated_at,new_role,member.business_role,new_status);
 SELECT * INTO member FROM public.workspace_members WHERE workspace_id=target_workspace_id AND user_id=member_user_id;
 RETURN result||jsonb_build_object('user_id',member_user_id,'status',new_status,'access_role',new_role,'updated_at',member.updated_at);
END; $function$

CREATE OR REPLACE FUNCTION public.platform_update_workspace(target_workspace_id uuid, actor_user_id uuid, expected_updated_at timestamp with time zone, section_name text, changes jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE workspace workspaces; before_values jsonb; after_values jsonb; allowed text[];
BEGIN
 SELECT * INTO workspace FROM workspaces WHERE id=target_workspace_id FOR UPDATE NOWAIT;
 PERFORM dation_private.team_actor(target_workspace_id,actor_user_id,true);
 IF workspace.updated_at IS DISTINCT FROM expected_updated_at THEN RAISE EXCEPTION 'Workspace changed; refresh' USING ERRCODE='55006'; END IF;
 IF section_name IS NULL OR section_name NOT IN('general','operation') OR changes IS NULL OR jsonb_typeof(changes)<>'object' THEN
 RAISE EXCEPTION 'Invalid settings section' USING ERRCODE='22023'; END IF;
 allowed=CASE WHEN section_name='general' THEN ARRAY['name','country','language','timezone'] ELSE ARRAY['currency','weight_unit','distance_unit','logistics_unit'] END;
 IF (changes-allowed)<>'{}'::jsonb OR NOT changes ?& allowed OR EXISTS(SELECT 1 FROM jsonb_each(changes) WHERE jsonb_typeof(value)<>'string') THEN
 RAISE EXCEPTION 'Invalid settings fields' USING ERRCODE='22023'; END IF;
 IF section_name='general' THEN
  IF length(trim(changes->>'name')) NOT BETWEEN 2 AND 120 OR changes->>'country' !~ '^[A-Z]{2}$' OR changes->>'language' NOT IN('es','en','pt')
   OR NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=changes->>'timezone') THEN RAISE EXCEPTION 'Invalid general preferences' USING ERRCODE='22023'; END IF;
  before_values=jsonb_build_object('name',workspace.name,'country',workspace.country,'language',workspace.language,'timezone',workspace.timezone);
  UPDATE workspaces SET name=trim(changes->>'name'),country=changes->>'country',language=changes->>'language',timezone=changes->>'timezone',updated_at=clock_timestamp()
   WHERE id=target_workspace_id RETURNING * INTO workspace;
  after_values=jsonb_build_object('name',workspace.name,'country',workspace.country,'language',workspace.language,'timezone',workspace.timezone);
 ELSE
  IF changes->>'currency' NOT IN('ARS','BRL','CLP','COP','EUR','MXN','PEN','USD','UYU') OR changes->>'weight_unit' NOT IN('kg','t')
   OR changes->>'distance_unit' NOT IN('km','mi') OR changes->>'logistics_unit' NOT IN('units','pallets','cases') THEN RAISE EXCEPTION 'Invalid operational preferences' USING ERRCODE='22023'; END IF;
  before_values=jsonb_build_object('currency',workspace.currency,'weight_unit',workspace.weight_unit,'distance_unit',workspace.distance_unit,'logistics_unit',workspace.logistics_unit);
  UPDATE workspaces SET currency=changes->>'currency',weight_unit=changes->>'weight_unit',distance_unit=changes->>'distance_unit',logistics_unit=changes->>'logistics_unit',updated_at=clock_timestamp()
   WHERE id=target_workspace_id RETURNING * INTO workspace;
  after_values=jsonb_build_object('currency',workspace.currency,'weight_unit',workspace.weight_unit,'distance_unit',workspace.distance_unit,'logistics_unit',workspace.logistics_unit);
 END IF;
 INSERT INTO audit_events(workspace_id,actor_user_id,event_type,metadata_json) VALUES(target_workspace_id,actor_user_id,'workspace.settings_updated',
  jsonb_build_object('section',section_name,'before',before_values,'after',after_values));
 RETURN jsonb_build_object('workspace',to_jsonb(workspace));
EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION 'Workspace is busy; refresh' USING ERRCODE='55006';
END; $function$

CREATE OR REPLACE FUNCTION public.platform_validate_decision_stage(target_workspace_id uuid, actor_user_id uuid, target_case_id uuid, target_node_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
 PERFORM dation_private.team_actor(target_workspace_id,actor_user_id);
 IF target_node_id NOT IN('logistics_assignment','logistics_scheduling') OR target_node_id IS NULL THEN RAISE EXCEPTION 'Invalid node' USING ERRCODE='22023'; END IF;
 PERFORM set_config('dation.actor_user_id',actor_user_id::text,true);
 PERFORM dation_private.require_workflow_responsibility(target_workspace_id,target_case_id,target_node_id,'configure');
 IF target_node_id='logistics_scheduling' AND NOT EXISTS(SELECT 1 FROM decision_runs
  WHERE workspace_id=target_workspace_id AND decision_case_id=target_case_id AND node_id='logistics_assignment'
   AND approved_at IS NOT NULL AND superseded_at IS NULL) THEN
  RAISE EXCEPTION 'Aprobá la decisión anterior antes de configurar.' USING ERRCODE='P0001'; END IF;
 RETURN jsonb_build_object('case_id',target_case_id,'node_id',target_node_id,'ready',true);
END; $function$

CREATE OR REPLACE FUNCTION public.platform_workflow_responsibilities(target_workspace_id uuid, actor_user_id uuid, target_case_id uuid, operation text DEFAULT 'read'::text, target_stage_key text DEFAULT NULL::text, expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone, new_owner_user_id uuid DEFAULT NULL::uuid, new_approver_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE role_name text; c decision_cases; stage dation_private.workflow_stage_assignments; result jsonb;
BEGIN
 IF operation IS NULL OR operation NOT IN('read','write') THEN RAISE EXCEPTION 'Invalid operation' USING ERRCODE='22023'; END IF;
 IF operation='write' THEN PERFORM 1 FROM workspaces WHERE id=target_workspace_id FOR UPDATE; END IF;
 role_name=dation_private.team_actor(target_workspace_id,actor_user_id,operation='write');
 SELECT * INTO c FROM decision_cases WHERE workspace_id=target_workspace_id AND id=target_case_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Case not found' USING ERRCODE='P0002'; END IF;
 IF operation='write' THEN
  IF c.status='archived' THEN RAISE EXCEPTION 'Restore case before assigning' USING ERRCODE='22023'; END IF;
  IF target_stage_key IS NULL OR target_stage_key NOT IN('data_preparation','data_owner','logistics_assignment','logistics_scheduling') THEN RAISE EXCEPTION 'Invalid stage' USING ERRCODE='22023'; END IF;
  IF target_stage_key IN('data_preparation','data_owner') THEN
   target_stage_key='data_owner';
   IF new_approver_user_id IS NOT NULL THEN RAISE EXCEPTION 'Data is not a decision node' USING ERRCODE='22023'; END IF;
   SELECT * INTO stage FROM dation_private.workflow_stage_assignments WHERE workspace_id=target_workspace_id AND decision_case_id=target_case_id AND stage_key='data_owner' FOR UPDATE;
   IF stage.updated_at IS DISTINCT FROM expected_updated_at THEN RAISE EXCEPTION 'Assignment changed' USING ERRCODE='55006'; END IF;
   IF new_owner_user_id IS DISTINCT FROM stage.owner_user_id THEN
    IF new_owner_user_id IS NOT NULL AND NOT dation_private.responsibility_eligible(target_workspace_id,new_owner_user_id,'data_owner') THEN RAISE EXCEPTION 'Assignee responsibility is not eligible' USING ERRCODE='22023'; END IF;
    INSERT INTO dation_private.workflow_stage_assignments VALUES(target_workspace_id,target_case_id,'data_owner',new_owner_user_id,actor_user_id,clock_timestamp())
     ON CONFLICT(workspace_id,decision_case_id,stage_key) DO UPDATE SET owner_user_id=excluded.owner_user_id,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
    INSERT INTO audit_events(workspace_id,actor_user_id,event_type,object_type,object_id,decision_case_id,metadata_json)
     VALUES(target_workspace_id,actor_user_id,'stage.responsible_changed','decision_case',target_case_id,target_case_id,
      jsonb_build_object('stage_key','data_owner','previous_user_id',stage.owner_user_id,'new_user_id',new_owner_user_id));
   END IF;
  ELSE
   PERFORM public.platform_assign_decision(target_workspace_id,actor_user_id,target_case_id,target_stage_key,expected_updated_at,new_owner_user_id,new_approver_user_id);
  END IF;
 END IF;
 WITH stages AS (
  SELECT 'data_owner' key,a.owner_user_id,a.updated_at FROM (SELECT 1) x LEFT JOIN dation_private.workflow_stage_assignments a
   ON a.workspace_id=target_workspace_id AND a.decision_case_id=target_case_id AND a.stage_key='data_owner'
  UNION ALL SELECT n.key,a.owner_user_id,a.updated_at FROM (VALUES('logistics_assignment'),('logistics_scheduling')) n(key)
   LEFT JOIN decision_assignments a ON a.workspace_id=target_workspace_id AND a.decision_case_id=target_case_id AND a.node_id=n.key)
 SELECT jsonb_object_agg(key,jsonb_build_object('owner',dation_private.team_person(target_workspace_id,owner_user_id),'updated_at',updated_at,
  'approver',CASE WHEN key='data_owner' THEN NULL ELSE dation_private.team_person(target_workspace_id,owner_user_id) END,
  'approver_eligible',key<>'data_owner' AND dation_private.responsibility_eligible(target_workspace_id,owner_user_id,'decision_owner'),
  'owner_eligible',dation_private.responsibility_eligible(target_workspace_id,owner_user_id,CASE WHEN key='data_owner' THEN 'data_owner' ELSE 'decision_owner' END),
  'can_execute',role_name IN('admin','operator') AND (role_name='admin' OR owner_user_id=actor_user_id),
  'can_approve',role_name IN('admin','operator') AND (role_name='admin' OR owner_user_id=actor_user_id))) INTO result FROM stages;
 result=jsonb_set(result,'{data_preparation}',result->'data_owner');
 RETURN jsonb_build_object('case_id',target_case_id,'stages',result,'can_assign',role_name='admin' AND c.status<>'archived',
  'can_prepare',role_name<>'viewer','gates_enforced',(SELECT workflow_gates_enabled FROM dation_private.platform_release WHERE singleton),
  'attributes_applied',c.attributes_applied_at IS NOT NULL,'policy_version',c.workflow_policy_version);
END; $function$

CREATE OR REPLACE FUNCTION public.protect_comparative_analysis()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'dation_private', 'public', 'pg_temp'
AS $function$
BEGIN
 IF NEW.id IS DISTINCT FROM OLD.id OR NEW.base_run_id IS DISTINCT FROM OLD.base_run_id OR
    NEW.base_result_fingerprint IS DISTINCT FROM OLD.base_result_fingerprint OR
    (NEW.request_json-'_observability') IS DISTINCT FROM (OLD.request_json-'_observability') THEN
  RAISE EXCEPTION 'Comparative identity is immutable' USING ERRCODE='22023';
 END IF;
 IF OLD.status='completed' AND NEW IS DISTINCT FROM OLD THEN
  RAISE EXCEPTION 'Completed comparative evidence is immutable' USING ERRCODE='22023';
 END IF;
 IF NEW.generation IS DISTINCT FROM OLD.generation AND NOT
    (OLD.status='error' AND NEW.status='queued' AND NEW.generation=OLD.generation+1) THEN
  RAISE EXCEPTION 'Invalid comparative retry' USING ERRCODE='22023';
 END IF;
 RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.protect_persistence_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'dation_private', 'public', 'pg_temp'
AS $function$
BEGIN
 IF TG_TABLE_NAME='datasets' THEN
   IF ROW(NEW.id,NEW.created_at,NEW.storage_bucket,NEW.storage_path,NEW.sha256,NEW.size_bytes,NEW.original_filename,NEW.dataset_type)
      IS DISTINCT FROM ROW(OLD.id,OLD.created_at,OLD.storage_bucket,OLD.storage_path,OLD.sha256,OLD.size_bytes,OLD.original_filename,OLD.dataset_type) THEN
     RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='La identidad del archivo persistido es inmutable';
   END IF;
 ELSIF TG_TABLE_NAME='decision_cases' THEN
   IF ROW(NEW.id,NEW.created_at,NEW.domain,NEW.orders_dataset_id,NEW.fleet_dataset_id,NEW.input_signature)
      IS DISTINCT FROM ROW(OLD.id,OLD.created_at,OLD.domain,OLD.orders_dataset_id,OLD.fleet_dataset_id,OLD.input_signature) THEN
     RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='El Data Pack del Decision Case es inmutable';
   END IF;
 ELSE
   IF ROW(NEW.id,NEW.created_at,NEW.dataset_id,NEW.orders_dataset_id,NEW.fleet_dataset_id,NEW.engine_name,NEW.engine_version,NEW.schema_version)
      IS DISTINCT FROM ROW(OLD.id,OLD.created_at,OLD.dataset_id,OLD.orders_dataset_id,OLD.fleet_dataset_id,OLD.engine_name,OLD.engine_version,OLD.schema_version)
      OR (NEW.configuration_json #- '{decision_case,status}' #- '{decision_case,approved_at}')
        IS DISTINCT FROM (OLD.configuration_json #- '{decision_case,status}' #- '{decision_case,approved_at}') THEN
     RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='La identidad y configuración de la corrida son inmutables';
   END IF;
   IF OLD.status IN ('completed','error') AND (
     ROW(NEW.status,NEW.started_at,NEW.finished_at,NEW.duration_ms,NEW.input_fingerprint,NEW.result_fingerprint,NEW.summary_json,NEW.error_message)
       IS DISTINCT FROM ROW(OLD.status,OLD.started_at,OLD.finished_at,OLD.duration_ms,OLD.input_fingerprint,OLD.result_fingerprint,OLD.summary_json,OLD.error_message)
     OR (NEW.result_json #- '{decision_case,status}' #- '{decision_case,approved_at}')
       IS DISTINCT FROM (OLD.result_json #- '{decision_case,status}' #- '{decision_case,approved_at}')) THEN
     RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='El resultado terminal de la corrida es inmutable';
   END IF;
   IF OLD.approved_at IS NOT NULL AND ROW(NEW.approved_at,NEW.approved_by) IS DISTINCT FROM ROW(OLD.approved_at,OLD.approved_by)
      OR OLD.superseded_at IS NOT NULL AND ROW(NEW.superseded_at,NEW.superseded_by_run_id) IS DISTINCT FROM ROW(OLD.superseded_at,OLD.superseded_by_run_id) THEN
     RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='Una aprobación histórica no puede reactivarse ni reescribirse';
   END IF;
 END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.report_dispatch_worker(target_worker_id uuid, worker_revision text, is_ready boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'dation_private', 'public', 'pg_temp'
AS $function$
BEGIN
 IF target_worker_id IS NULL OR worker_revision IS NULL OR is_ready IS NULL THEN
  RAISE EXCEPTION 'Invalid worker report' USING ERRCODE='22023';
 END IF;
 INSERT INTO dispatch_worker_instances VALUES(target_worker_id,worker_revision,clock_timestamp(),is_ready)
 ON CONFLICT(worker_id) DO UPDATE SET revision=excluded.revision,seen_at=excluded.seen_at,ready=excluded.ready;
 DELETE FROM dispatch_worker_instances WHERE seen_at < clock_timestamp()-interval '24 hours';
 RETURN true;
END; $function$

CREATE OR REPLACE FUNCTION public.validate_current_run_admission()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'dation_private', 'public', 'pg_temp'
AS $function$
DECLARE source public.decision_runs%rowtype;
BEGIN
 IF NEW.decision_case_id IS NULL THEN RETURN NEW; END IF;
 PERFORM 1 FROM public.decision_cases WHERE id=NEW.decision_case_id FOR UPDATE;
 IF NEW.upstream_run_id IS NOT NULL THEN
   SELECT * INTO source FROM public.decision_runs WHERE id=NEW.upstream_run_id;
   IF NOT FOUND OR source.status<>'completed' OR source.approved_at IS NULL OR source.superseded_at IS NOT NULL THEN
     RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='La corrida upstream ya no es la decisión aprobada vigente';
   END IF;
   IF source.upstream_run_id IS NOT NULL AND NOT EXISTS (
     SELECT 1 FROM public.decision_runs r WHERE r.id=source.upstream_run_id
     AND r.decision_case_id=NEW.decision_case_id AND r.status='completed' AND r.approved_at IS NOT NULL AND r.superseded_at IS NULL) THEN
     RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='La cadena de decisiones upstream está desactualizada';
   END IF;
 END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_decision_run_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'dation_private', 'public', 'pg_temp'
AS $function$
declare
    case_orders uuid;
    case_fleet uuid;
    source_case uuid;
    source_node text;
    source_approved_at timestamptz;
    expected_source_node text;
begin
    if tg_op = 'UPDATE' then
        if new.decision_case_id is distinct from old.decision_case_id
           or new.node_id is distinct from old.node_id
           or new.upstream_run_id is distinct from old.upstream_run_id then
            raise exception 'La identidad y el lineage de una Decision Run son inmutables';
        end if;
    end if;

    if new.decision_case_id is null then
        if new.node_id is not null or new.upstream_run_id is not null then
            raise exception 'Una corrida sin Decision Case no puede declarar nodo o dependencia';
        end if;
        return new;
    end if;

    select orders_dataset_id, fleet_dataset_id
      into case_orders, case_fleet
      from public.decision_cases
     where id = new.decision_case_id;

    if not found then
        raise exception 'El Decision Case de la corrida no existe';
    end if;

    if new.orders_dataset_id is distinct from case_orders
       or new.fleet_dataset_id is distinct from case_fleet then
        raise exception 'La Decision Run usa un Data Pack distinto al Decision Case';
    end if;

    expected_source_node := case new.node_id
        when 'logistics_assignment' then null
        when 'logistics_scheduling' then 'logistics_assignment'
        when 'logistics_final_assignment' then 'logistics_scheduling'
        else null
    end;

    if expected_source_node is null then
        if new.upstream_run_id is not null then
            raise exception 'Assignment no admite una corrida upstream';
        end if;
    else
        if new.upstream_run_id is null then
            raise exception 'La decisión requiere una corrida upstream aprobada';
        end if;

        select decision_case_id, node_id, approved_at
          into source_case, source_node, source_approved_at
          from public.decision_runs
         where id = new.upstream_run_id;

        if not found
           or source_case is distinct from new.decision_case_id
           or source_node is distinct from expected_source_node
           or source_approved_at is null then
            raise exception 'El lineage de la Decision Run no corresponde al Decision Case';
        end if;
    end if;

    if new.approved_at is not null and new.status <> 'completed' then
        raise exception 'Sólo una corrida completada puede aprobarse';
    end if;

    return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_dispatch_run()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'dation_private', 'public', 'pg_temp'
AS $function$
begin
  if new.schema_version in ('dispatch_v1', 'dispatch_v2') then
    if new.orders_dataset_id is null
       or new.fleet_dataset_id is null
       or new.dataset_id <> new.orders_dataset_id then
      raise exception 'Una corrida dispatch requiere órdenes y flota';
    end if;

    if not exists (
      select 1
      from public.datasets
      where id = new.orders_dataset_id
        and dataset_type = 'orders'
    )
    or not exists (
      select 1
      from public.datasets
      where id = new.fleet_dataset_id
        and dataset_type = 'fleet'
    ) then
      raise exception 'Tipos de datasets incorrectos';
    end if;

    if new.status = 'completed'
       and new.result_json is not null
       and coalesce(new.result_json ->> 'schema_version', '') <> new.schema_version then
      raise exception 'La versión del resultado no coincide con la corrida';
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_interpretation_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'dation_private', 'public', 'pg_temp'
AS $function$
DECLARE actual uuid;
BEGIN
 IF NEW.analysis_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM decision_comparative_analyses WHERE id=NEW.analysis_id AND base_run_id=NEW.run_id AND status='completed') THEN
  RAISE EXCEPTION 'Comparative evidence unavailable' USING ERRCODE='22023';
 END IF;
 IF NEW.chat_turn_id IS NOT NULL THEN SELECT run_id INTO actual FROM decision_chat_turns WHERE turn_id=NEW.chat_turn_id;
 ELSE SELECT run_id INTO actual FROM decision_explanations WHERE id=NEW.explanation_id; END IF;
 IF actual IS DISTINCT FROM NEW.run_id THEN RAISE EXCEPTION 'Interpreter source mismatch' USING ERRCODE='22023'; END IF;
 RETURN NEW;
END; $function$
